Problem:
A cell-phone company makes foldable and regular cell-phones in a factory that is divided into a hardware and software section. The hardware section must work 10 hours on each foldable cell-phone but only 3 hours on each regular one. The software section must work 3 hours for each cell-phone. The profit from the foldable cell-phone is $500 and the profit from the regular cell-phone is $300. Due to a recent strike, the hardware section only has 200 hours available per week and the software section only has 150 hours available per week. How many of each phone should the company produce to maximize profit?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "foldable cell-phones produced",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "regular cell-phones produced",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "foldable cell-phones produced",
     "coef": 500.0
    },
    {
     "var": "regular cell-phones produced",
     "coef": 300.0
    }
   ]
  },
  "constraints": [
   {
    "name": "hardware hours",
    "terms": [
     {
      "var": "foldable cell-phones produced",
      "coef": 10.0
     },
     {
      "var": "regular cell-phones produced",
      "coef": 3.0
     }
    ],
    "sense": "<=",
    "rhs": 200.0
   },
   {
    "name": "software hours",
    "terms": [
     {
      "var": "foldable cell-phones produced",
      "coef": 3.0
     },
     {
      "var": "regular cell-phones produced",
      "coef": 3.0
     }
    ],
    "sense": "<=",
    "rhs": 150.0
   }
  ]
 },
 "facts": {
  "objective": 16400.0,
  "values": {
   "foldable cell-phones produced": 7.0,
   "regular cell-phones produced": 43.0
  },
  "binding": [
   "software hours"
  ],
  "slack": {
   "hardware hours": 1.0,
   "software hours": 0.0
  },
  "shadow_prices": null,
  "limits": {
   "hardware hours": {
    "dropped_improves": true,
    "loosened_improves": false
   },
   "software hours": {
    "dropped_improves": true,
    "loosened_improves": false
   }
  }
 }
}
